public class Ex02TryWithResources {
    static class MyResource implements AutoCloseable {
        final String name;
        MyResource(String name) { this.name = name; System.out.println(name + " opened"); }
        void use() { System.out.println(name + " used"); }
        public void close() { System.out.println(name + " closed"); }
    }
    public static void main(String[] args) {
        try (MyResource r1 = new MyResource("A");
             MyResource r2 = new MyResource("B")) {
            r1.use();
            r2.use();
        }
        System.out.println("after try-with-resources block");
    }
}
